```csharp
using System;

class Program
{
    static void Main(string[] args)
    {
        // Wellenlänge des Photons in Metern umrechnen
        double wavelength = 600 * Math.Pow(10, -9);

        // Lichtgeschwindigkeit
        double speedOfLight = 299792458;

        // Plancksche Konstante
        const double PlanckConstant = 6.62607004 * Math.Pow(10, -34);

        // Energie eines Photons
