   @Steps
   class InvoiceSteps {
       // Gibt einen Invoice-Objekt mit gefälschten Daten zurück
       def givenAnInvoiceObject(Map<String, String> invoiceDetails) {
           def invoice = new Invoice(invoiceNumber: invoiceDetails.invoiceNumber,
                                      customerName: invoiceDetails.customerName,
                                      billingAddress: invoiceDetails.billingAddress,
                                      shippingAddress: invoiceDetails.shippingAddress,
                                      emailed: Boolean.parseBoolean(invoiceDetails.emailed),
                                      createdDate: Instant.parse(invoiceDetails.createdDate))

           // Insert the Invoice into Oracle EBS using any appropriate connection and CRUD operations
           Persistence.insert(entityManager, invoice)

           // Return the created invoice
           new JsonBuilder(invoice).toPrettyString()
       }

       // Sendet einen POST-Antrag an die Ressource /invoices
       def whenTheClientSendsAPostRequest(strEndpoint, objBody) {
           // Simuliere den HTTP-POST-Aufruf
           post("${env['SERVER_URL']}${strEndpoint}", contentType: 'application/json', body: objBody)
       }

       // Prüft den Antwort-Status-Code
       def thenTheServerShouldRespondWithStatus(int expectedStatusCode) {
           expectedStatusCode == response.statuscode
       }

       // Validate the response & store the invoice details for future use
       def andTheResponseShouldContainAnInvoiceWith(Map<String, String> expectedInvoiceDetails) {
           def actualInvoice = new ObjectMapper().readValue(response.body, Invoice)

           expectedInvoiceDetails.each { field, value ->
               assert actualInvoice[field] == value
           }
       }

       // Prüft ob die Rechnung erfolgreich in Oracle EBS erstellt wurde
       def andTheInvoiceIsSuccessfullyCreatedInOracleEbs() {
           // Implementiere spezifische Konsistenzprüfungen für die Datenbank Oracle EBS
           def queryResult = entityManager.createQuery('SELECT r FROM Rechnung r WHERE r.Rechnungsnummer = ?', Rechnung).setParameter(0, expectedInvoiceDetails.invoiceNumber).getResultList()

           assert queryResult.size() == 1
           assert queryResult.first().getKundenname() == expectedInvoiceDetails.customerName
           assert queryResult.first().getRechnungsadresse() == expectedInvoiceDetails.billingAddress
           assert queryResult.first().getLieferadresse() == expectedInvoiceDetails.shippingAddress
       }
   }
