import org.apache.commons.math3.ml.distance.DistanceMeasureFactory
import org.apache.commons.math3.ml.distance.ManhattanDistance

import scala.io.Source

case class BusinessData(
  revenue: Double,
  profitMargin: Double,
  brandImage: Double,
  marketSegment: String,
  industry: String
)

// Funktion zur Lesung der Datei und Rückgabe einer Liste von BusinessData-Objekten
def readBusinessData(file: String): List[BusinessData] = {
  val data = Source.fromFile(file).getLines().toList.map(line => {
    val fields = line.split(",").map(_.trim)
    BusinessData(
      revenue = fields(0).toDouble,
      profitMargin = fields(1).toDouble,
      brandImage = fields(2).toDouble,
      marketSegment = fields(3),
      industry = fields(4)
    )
  })

  // Hier könnte man weitere Vorverarbeitungs-Schritte überlegen, z.B. Mangelnde Werte füllen oder Verzerrungen eliminieren
  data
}

// Funktion zur Identifizierung der fünf wichtigsten Merkmale
def findMostImportantFeatures(data: List[BusinessData]): List[String] = {
  // Implementieren Sie Ihre bevorzugte Metrik zur Merkmalsauswahl hier (z.B. Korrelation, Regressionsanalyse usw.)
  val featureCorrelations = data.map(d => {
    val feature_vector = Array(d.revenue, d.profitMargin, d.brandImage)
    feature_vector.correlation
  })

  val sortedFeatures = featureCorrelations.zipWithIndex.map { case (corr, index) => (corr, s"Feature ${index + 1}") }.sortBy(_._1)(Ordering[Double].reverse).take(5).map(_._2)

  sortedFeatures
}

// Funktion zur Skalierung der Merkmale mit Berücksichtigung der Datenvielfalt
def scaleFeatures(data: List[BusinessData], featuresToScale: List[String], scalingMethod: String): List[BusinessData] = {
  val (minValues, maxValues) = featuresToScale.map(feature => {
    val min = data.map(_.apply(feature)).min
    val max = data.map(_.apply(feature)).max
    (min, max)
  }).unzip

  val scalingFunction = scalingMethod.toLowerCase match {
    case "minmax" => (x: Double) => (x - minValues.head) / (maxValues.head - minValues.head)
    case "standardization" => (x: Double) => (x - data.map(_.apply(feature)).mean) / data.map(_.apply(feature)).standardDeviation
    case "logarithmic" => (x: Double) => math.log10(x)
    case _ => throw new Exception("Unknown scaling method: " + scalingMethod)
  }

  def scaleFeature(feature: String): Double => Double = {
    scalingFunction(_: Double)
  }

  data.map(bd => {
    BusinessData(
      revenue = scaleFeature("revenue")(bd.revenue),
      profitMargin = scaleFeature("profitMargin")(bd.profitMargin),
      brandImage = scaleFeature("brandImage")(bd.brandImage),
      marketSegment = bd.marketSegment,
      industry = bd.industry
    )
  })
}

// Funktion zur Erkennung und Korrektion von Verzerrungen
def correctOutliers(data: List[BusinessData], toleranceIncrement: Double): List[BusinessData] = {
  // Implementieren Sie Ihre bevorzugte Methode zur Erkennung und Korrektion von Ausreißern hier (z.B. Z-score, Mahalanobis-Distanz usw.)
  val mahalanobisDistances = new DistanceMeasureFactory().getMahalanobisDistance(
    dataset = data.map(bd => Seq(bd.revenue, bd.profitMargin, bd.brandImage)),
    covarianceMatrixStrategy = org.apache.commons.math3.ml.distance.CovarianceMatrixStrategy.COVARIANCE
  )

  def isOutlier(row: Seq[Double], distanceThreshold: Double) = {
    mahalanobisDistances.distance(row) > distanceThreshold
  }

  val distanceThreshold = data.map(_ => mahalanobisDistances.distance(_)).mean + (toleranceIncrement * data.map(_ => mahalanobisDistances.distance(_)).standardDeviation)

  def correctOutlier(bd: BusinessData): BusinessData = {
    if (isOutlier(Seq(bd.revenue, bd.profitMargin, bd.brandImage), distanceThreshold)) {
      // Implementieren Sie hier eine geeignete Methode zur Korrektur von Ausreißern, z.B. Mittelwert, Median, Max/Min-Wert oder PCA
      BusinessData(
        revenue = data.filter(!isOutlier(_, distanceThreshold)).map(_.revenue).mean,
        profitMargin = data.filter(!isOutlier(_, distanceThreshold)).map(_.profitMargin).mean,
        brandImage = data.filter(!isOutlier(_, distanceThreshold)).map(_.brandImage).mean,
        marketSegment = bd.marketSegment,
        industry = bd.industry
      )
    } else {
      bd
    }
  }

  data.map(correctOutlier)
}

// Beispielfunktionsaufrufen: Hier kannst du den scala-Code an deinen Datensatz anpassen und ausführen
val businessData = readBusinessData("business_data.csv")
