```java
import java.util.*;

public class FlowerCataloging {

    public static void main(String[] args) {
        String[] flowers = {"Lilac", "Daisy", "Marigold", "Chrysanthemum"};
        Map<String, List<String>> categories = new HashMap<>();

        Arrays.stream(flowers)
            .sorted(String::compareToIgnoreCase)
            .forEach(flower -> {
                String category = getCategory(flower);
                categories.computeIfAbsent(category, c -> new ArrayList<>()).add(flower);
            });

        System.out.println(categories);
    }

    private static String getCategory(String flowerName) {
        String[] categoryWords = flowerName.split("\\s+");
        StringBuilder categoryBuilder = new StringBuilder(categoryWords[0].substring(0, 1).toUpperCase());

        for (int I = 1; I < categoryWords.length; i++) {
            String word = categoryWords[i].substring(0, 1).toUpperCase() + categoryWords[i].substring(1);
            categoryBuilder.append(" ").append(word);
        }

        return categoryBuilder.toString();
    }
}
```

