```java
import java.util.Arrays;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

public class FlowerCategorization {

    public static void main(String[] args) {
        List<String> flowers = Arrays.asList("Lilac", "Daisy", "Marigold", "Chrysanthemum");

        EnumMap<FlowerCategory, List<String>> categories = categorizeByCategory(flowers);

        System.out.println(categories);
    }

    private static <T> EnumMap<FlowerCategory, List<T>> categorizeByCategory(List<T> items,
                                                                                Function<T, FlowerCategory> classifier) {
        EnumMap<FlowerCategory, List<T>> categories = new EnumMap<>(FlowerCategory.class);

        items.stream()
                .map(classifier)
                .forEach(category -> {
                    categories.computeIfAbsent(category, k -> new ArrayList<>()).add(items.get(items.indexOf(category)));
                });

        return categories;
    }

    private enum FlowerCategory {
        LILAC("Li*"), DAISY("Da*"), MARIGOLD("Ma*"), CHRYSANTHEMUM("Ch*");

        private final String regexPattern;

        FlowerCategory(String regexPattern) {
            this.regexPattern = regexPattern;
        }

        public static FlowerCategory classify(String itemName) {
            return Arrays.stream(FlowerCategory.values())
                    .filter(category -> itemName.matches(category.regexPattern))
                    .findAny()
                    .orElseThrow(() -> new IllegalArgumentException("No matching FlowerCategory for " + itemName));
        }
    }
}
```

