```java
import java.io.File;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

public class CubeXMLReader {

    public Cube readFromXml(String filePath) throws Exception {
        DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
        DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();

        Document doc = dBuilder.parse(new File(filePath));

        Cube cube = new Cube();

        NodeList cubeLayerNodes = doc.getElementsByTagName("layer");
        for (int i = 0; i < cubeLayerNodes.getLength(); i++) {
            Element layerEl = (Element) cubeLayerNodes.item(i);
            NodeList faceNodes = layerEl.getElementsByTagName("face");
            List<Face> faces = new ArrayList<>();
            for (int j = 0; j < faceNodes.getLength(); j++) {
                Element faceEl = (Element) faceNodes.item(j);
                int faceId = Integer.parseInt(faceEl.getAttribute("id"));
                String color = faceEl.getTextContent().trim();
                Face f = new Face(faceId, color);
                faces.add(f);
            }
            cube.getLayers().set(i, faces);
        }

        return cube;
    }
}
```

