   function rule(context) {
     return {
       // Lifecycle Hook Handler
       'vue-hooks(beforeCreate|created|beforeMount|mounted|beforeUpdate|updated|activated|deactivated|beforeDestroy|destroyed|errorCaptured)':
         (node) => {
           // Regelverletzung überprüfen
           const methodName = node.key.name;
           const nodeParent = node.parent;

           if (
             methodName !== 'created' &&
             (nodeParent.type === 'Method' ||
               (nodeParent.type === 'CallExpression' &&
                 nodeParent.callee.property &&
                 nodeParent.callee.property.name === 'watch'))
