             let flag2 = false;
             let dataPropNode;

             // Data Properties `data()` Handler
             if (nodeParent.type === 'Method' && nodeParent.key.name === 'data') {
               dataPropNode = nodeParent.body.body.find(
                 (x) => x.type === 'ObjectExpression'
               );
