             // Update State Directly Handler
             if (
               ((dataPropNode && dataPropNode.properties.some((x) => x.key.name === methodName)) ||
                 (nodeParent.type === 'CallExpression' &&
                   nodeParent.arguments.some((arg) => arg.type === 'Identifier' && arg.name === methodName))) &&
               !context.getScope().hasOwnBinding(methodName)
             ) {
               flag = true;
             }

             // Update State Indirectly Handler
             const dependentProperties = context.getDependentVariables(methodName);
             if (dependentProperties.length > 0) {
               flag2 = true;
             }

             // Meldung für Update State Direkt
             if (flag) {
               context.report({
                 message:
                   'Lifecycle hook method "{{ methodName }}" should not update internal component state directly (at {{ line }}, column {{ column }}).',
                 node,
                 data: { methodName },
               });
             }

             // Meldung für Update State Indirekt
             if (flag2) {
               context.report({
                 message:
                   'Lifecycle hook method "{{ methodName }}" should not indirectly update internal component state through calling another method (at {{ line }}, column {{ column }}).',
                 node,
                 data: { methodName },
               });
             }
         },
     };
   }
